// Facebook webhook-оос ирсэн мессеж/postback-ийг задлах
// Текст мессеж + Get Started/Ice Breaker postback-ийг боловсруулна.
const body = $input.first().json.body;
if (!body || body.object !== 'page') return [];

// Get Started болон Ice Breaker payload-уудыг текст асуулт болгон хөрвүүлнэ
// → AI Agent ердийн хайлт/хариулт хийнэ.
const PAYLOAD_TO_TEXT = {
  GET_STARTED: '__GET_STARTED__',
  IB_PROJECTS: 'бэлэн төсөл',
  IB_BOOKS: 'ном',
  IB_PRICING: 'үнэ төлбөрийн мэдээлэл',
  IB_DOWNLOAD: 'татаж авах заавар',
};

const out = [];
for (const entry of (body.entry || [])) {
  for (const msg of (entry.messaging || [])) {
    const psid = String(msg.sender && msg.sender.id || '');
    if (!psid) continue;

    // 1) Postback (Get Started товч, Ice Breaker асуулт)
    if (msg.postback && msg.postback.payload) {
      const mapped = PAYLOAD_TO_TEXT[msg.postback.payload];
      const text = mapped || String(msg.postback.title || msg.postback.payload).trim();
      out.push({ json: { psid, text, isPostback: true } });
      continue;
    }

    // 2) Энгийн текст мессеж (echo, attachment алгасна)
    if (msg.message && !msg.message.is_echo && msg.message.text) {
      out.push({ json: { psid, text: String(msg.message.text).trim(), isPostback: false } });
    }
  }
}
return out;

const NL = String.fromCharCode(10);
const psid = $('Parse').first().json.psid;
const userText = $('Parse').first().json.text;
const profile = $('Get User Profile').first().json || {};
const firstName = (profile.first_name || '').trim();
const search = $('Search DigitalGer').first().json || {};
const products = Array.isArray(search.products) ? search.products : [];
const searchTerms = Array.isArray(search.searchTerms) ? search.searchTerms : [];
const fmt = (n0)=>{ let n=Math.round(Number(n0)||0),str=String(n),out='',c=0; for(let i=str.length-1;i>=0;i--){out=str[i]+out;c++;if(c%3===0&&i>0)out=','+out;} return out+String.fromCharCode(0x20AE); };
const isGetStarted = (userText === '__GET_STARTED__');
const nameLine = firstName ? ('Хэрэглэгчийн нэр: ' + firstName) : '';
const showProducts = (searchTerms.length > 0) && (products.length > 0) && !isGetStarted;
let productsBlock = '';
if (showProducts) {
  productsBlock = products.slice(0,5).map(function(p,i){
    var pr=(p.salePrice!=null)?('Үнэ: '+fmt(p.salePrice)+' (хуучин '+fmt(p.price)+')'):('Үнэ: '+fmt(p.price));
    return (i+1)+'. '+p.title+NL+'   '+pr+NL+'   '+String(p.description||'').slice(0,120);
  }).join(NL+NL);
}
let agentInput;
if (isGetStarted) {
  agentInput = [nameLine, '=== ОНЦГОЙ: хэрэглэгч анх удаа орж ирлээ. Дулаан угтах мэндчилгээ бич, DigitalGer-ийг товч танилцуул. ==='].filter(Boolean).join(NL);
} else if (showProducts) {
  agentInput = [
    nameLine,
    '=== ХЭРЭГЛЭГЧИЙН МЕССЕЖ ===', userText, '',
    '=== НӨХЦӨЛ: Энэ бол БҮТЭЭГДЭХҮҮНИЙ хайлт. Доорх бүтээгдэхүүнүүд АВТОМАТААР картаар харагдана. Чи зөвхөн 1-2 өгүүлбэр богино танилцуулга бич. Бүтээгдэхүүний нэр/үнэ/холбоос БҮҮ жагсаа. ===',
    productsBlock,
  ].filter(Boolean).join(NL);
} else {
  agentInput = [
    nameLine,
    '=== ХЭРЭГЛЭГЧИЙН МЕССЕЖ ===', userText, '',
    '=== НӨХЦӨЛ: Энэ бол ерөнхий асуулт/мэндчилгээ/FAQ. Системийн мэдлэгээсээ ШУУД эелдэг хариул. Бүтээгдэхүүн санал болгох шаардлагагүй. ===',
  ].filter(Boolean).join(NL);
}
return [{ json: { psid, userText, firstName, agentInput, products, searchTerms, showProducts } }];

const NL = String.fromCharCode(10);
const TUG = String.fromCharCode(0x20AE);
const prep = $('Prep Context').first().json;
const psid = prep.psid;
const products = prep.products || [];
const showProducts = prep.showProducts === true && products.length > 0;
let replyText = ($input.first().json.output || '').trim();
function stripMd(s){ s=String(s||''); var r='',i=0; while(i<s.length){ if(s[i]==='['){ var c=s.indexOf('](',i); if(c!==-1){ var e=s.indexOf(')',c+2); if(e!==-1){ r+=s.slice(i+1,c)+' '+s.slice(c+2,e); i=e+1; continue; } } } r+=s[i]; i++; } return r.split('**').join('').split('__').join('').split('[SHOW_PRODUCTS]').join('').trim(); }
replyText = stripMd(replyText);
if (!replyText) replyText = showProducts ? 'Танд тохирох бүтээгдэхүүн оллоо 👇' : 'Уучлаарай, дахин бичнэ үү.';
if (replyText.length > 1900) replyText = replyText.slice(0,1897)+'...';
if (!showProducts) { return [{ json: { psid, replyText, hasCards:false, elements:[] } }]; }
const clip=function(s,m){ s=String(s||'').split(NL).join(' ').trim(); while(s.indexOf('  ')!==-1) s=s.split('  ').join(' '); return s.length>m?s.slice(0,m-1).trim()+'…':s; };
const fmt=function(n0){ var n=Math.round(Number(n0)||0),str=String(n),out='',c=0; for(var i=str.length-1;i>=0;i--){out=str[i]+out;c++;if(c%3===0&&i>0)out=','+out;} return out+TUG; };
const elements = products.slice(0,10).map(function(p){
  var priceLine=(p.salePrice!=null)?('💰 '+fmt(p.salePrice)+'  ·  хуучин '+fmt(p.price)):('💰 '+fmt(p.price));
  var room=79-priceLine.length; var desc=room>12?clip(p.description,room):'';
  var subtitle=desc?clip(priceLine+NL+desc,80):clip(priceLine,80);
  var el={ title:clip(p.title,80), subtitle:subtitle, default_action:{type:'web_url',url:p.url,webview_height_ratio:'full'}, buttons:[{type:'web_url',url:p.url,title:'Дэлгэрэнгүй үзэх'}] };
  if(p.imageUrl) el.image_url=p.imageUrl;
  return el;
});
return [{ json: { psid, replyText, hasCards:elements.length>0, elements } }];
